# region: fold
def fold(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: gather
def gather(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
        return out
    return out

# region: render
def render(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: intake
def intake(summary, bar=3):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return intake(render(gather(fold(raw))))

